// Let a map editor undo and redo painting a tile.
// level-editor-undo: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,...[operation,cell,value]]
// Output: [...final_grid]
// Operations: 0 paint, 1 undo, 2 redo. Cell ID is y*width+x. New paint discards the redo branch.
// Ignored unused cell/value fields must still be supplied.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#![allow(unused_assignments, unused_mut, dead_code, unused_parens)]
// Count how many numbers are in this list.
fn port_length(a: &[f64]) -> f64 { a.len() as f64 }
// Read one number at a zero-based position; stop if that position does not exist.
fn port_get(a: &[f64], i:f64) -> f64 { assert!(i.is_finite() && i>=0.0 && i.fract()==0.0 && i<(a.len() as f64)); a[i as usize] }
// Replace a number at an existing position in the list.
fn port_put(i:f64, v:f64, a: &mut Vec<f64>) { port_get(a,i); a[i as usize]=v; }
// Add one number to the end of the list.
fn port_push(v:f64, a: &mut Vec<f64>) { a.push(v); }

// 1. Before painting, remember the old tile and the new tile.
// 2. Undo restores the old tile and moves backward in the edit history.
// 3. Redo puts the new tile back and moves forward.
// 4. Painting after undo throws away the abandoned future edits.
pub fn compute(data: &[f64]) -> Vec<f64> {
    let mut w: f64 = 0.0;
    let mut h: f64 = 0.0;
    let mut grid: Vec<f64> = Vec::new();
    let mut history: Vec<f64> = Vec::new();
    let mut cursor: f64 = 0.0;
    let mut i: f64 = 0.0;
    let mut operation: f64 = 0.0;
    let mut cell: f64 = 0.0;
    let mut value: f64 = 0.0;
    let mut kept: Vec<f64> = Vec::new();
    let mut j: f64 = 0.0;
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    if ((w < 1.0) || (h < 1.0)) {
        return vec![-(1.0)];
    }
    grid = vec![];
    history = vec![];
    cursor = 0.0;
    i = 0.0;
    while (i < (w * h)) {
        port_push(0.0, &mut grid);
        i += 1.0;
    }
    i = 2.0;
    while (i < port_length(&data)) {
        operation = port_get(&data, i);
        cell = port_get(&data, (i + 1.0));
        value = port_get(&data, (i + 2.0));
        if (operation == 0.0) {
            if ((cell < 0.0) || (cell >= (w * h))) {
                return vec![-(1.0)];
            }
            kept = vec![];
            j = 0.0;
            while (j < (cursor * 3.0)) {
                port_push(port_get(&history, j), &mut kept);
                j += 1.0;
            }
            history = kept.clone();
            port_push(cell, &mut history);
            port_push(port_get(&grid, cell), &mut history);
            port_push(value, &mut history);
            cursor += 1.0;
            port_put(cell, value, &mut grid);
        } else {
            if ((operation == 1.0) && (cursor > 0.0)) {
                cursor -= 1.0;
                port_put(port_get(&history, (cursor * 3.0)), port_get(&history, ((cursor * 3.0) + 1.0)), &mut grid);
            } else {
                if ((operation == 2.0) && ((cursor * 3.0) < port_length(&history))) {
                    port_put(port_get(&history, (cursor * 3.0)), port_get(&history, ((cursor * 3.0) + 2.0)), &mut grid);
                    cursor += 1.0;
                }
            }
        }
        i += 3.0;
    }
    return grid;
}
